{
  "findings": [
    {
      "ref": "[D524]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with a child on Roblox.",
      "stance": "risk",
      "quote": "Roblox’s default settings, including unverified accounts, no age verification, and open communication channels, repeatedly exposed minors to sexual exploitation."
    },
    {
      "ref": "[D524]",
      "area": "age_gating",
      "claim": "A parent reports that Roblox’s age gating does not work in practice.",
      "stance": "risk",
      "quote": "Until 2024, the platform allegedly allowed anyone to message or send friend requests to anyone else without requiring accounts to be tied to a phone number, e-mail address, or government ID."
    },
    {
      "ref": "[D524]",
      "area": "content",
      "claim": "A parent reports that Roblox hosts sexually explicit content and child sexual abuse material.",
      "stance": "risk",
      "quote": "The county also alleges that Roblox hosted sexually explicit content and that thousands of users shared child sexual abuse material on the platform."
    },
    {
      "ref": "[D524]",
      "area": "data",
      "claim": "A parent reports that Roblox collects personal information and shares it with third parties.",
      "stance": "risk",
      "quote": "The complaint alleges that Lenovo’s website deploys approximately 55 tracking technologies, including web beacons, pixels, cookies, APIs, and software development kits from third parties such as TikTok, Facebook, Google, and Microsoft, to collect information from over 100,000 U.S. consumers."
    },
    {
      "ref": "[D524]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced lawsuits and regulatory actions over child safety and data practices.",
      "stance": "risk",
      "quote": "Los Angeles County filed a civil lawsuit against Roblox Corporation alleging the company falsely marketed its online gaming platform as safe for children while knowingly allowing it to become a “hunting ground for predators.”"
    }
  ]
}
